changeSet.sql:
CREATE TABLE media_time_correction (
    media_id BIGINT PRIMARY KEY REFERENCES media_file(id) ON DELETE CASCADE,
    offset_seconds INTEGER NOT NULL CHECK (offset_seconds BETWEEN -86400 AND 86400),
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE media_manual_location (
    media_id BIGINT PRIMARY KEY REFERENCES media_file(id) ON DELETE CASCADE,
    location geometry(Point, 4326) NOT NULL,
    note VARCHAR(1000),
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT media_manual_location_latitude_check
        CHECK (ST_Y(location) BETWEEN -90 AND 90),
    CONSTRAINT media_manual_location_longitude_check
        CHECK (ST_X(location) BETWEEN -180 AND 180)
);

CREATE TABLE media_track_correlation (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    media_id BIGINT NOT NULL REFERENCES media_file(id) ON DELETE CASCADE,
    track_id BIGINT NOT NULL REFERENCES gps_track(id) ON DELETE CASCADE,
    track_version BIGINT NOT NULL,
    algorithm_version INTEGER NOT NULL,
    captured_at TIMESTAMP NOT NULL,
    adjusted_capture_time TIMESTAMP NOT NULL,
    applied_camera_offset_seconds INTEGER NOT NULL,
    time_source VARCHAR(32) NOT NULL CHECK (time_source IN ('EXIF_GPS', 'EXIF_DATE_TAKEN')),
    route_location geometry(Point, 4326) NOT NULL,
    distance_in_meter_since_start DOUBLE PRECISION,
    duration_since_start_seconds DOUBLE PRECISION,
    track_point_index INTEGER,
    track_point_time_delta_seconds DOUBLE PRECISION,
    exif_route_distance_meters DOUBLE PRECISION,
    selected BOOLEAN NOT NULL DEFAULT FALSE,
    alternative_count INTEGER NOT NULL DEFAULT 1 CHECK (alternative_count > 0),
    ambiguous BOOLEAN NOT NULL DEFAULT FALSE,
    calculated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT media_track_correlation_media_track_uq UNIQUE (media_id, track_id)
);

CREATE UNIQUE INDEX media_track_correlation_ix_selected_media
    ON media_track_correlation(media_id)
    WHERE selected;
CREATE INDEX media_track_correlation_ix_track_timeline
    ON media_track_correlation(track_id, adjusted_capture_time, media_id)
    WHERE selected;
CREATE INDEX media_track_correlation_ix_media
    ON media_track_correlation(media_id);
CREATE INDEX media_track_correlation_ix_route_location
    ON media_track_correlation USING gist(route_location);

CREATE TABLE media_resolved_location (
    media_id BIGINT PRIMARY KEY REFERENCES media_file(id) ON DELETE CASCADE,
    location geometry(Point, 4326) NOT NULL,
    position_origin VARCHAR(32) NOT NULL
        CHECK (position_origin IN ('EXIF_EMBEDDED', 'TRACK_INTERPOLATED', 'USER_ASSIGNED')),
    correlation_id BIGINT REFERENCES media_track_correlation(id) ON DELETE CASCADE,
    resolved_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT media_resolved_location_correlation_check CHECK (
        (position_origin = 'TRACK_INTERPOLATED' AND correlation_id IS NOT NULL)
        OR (position_origin <> 'TRACK_INTERPOLATED' AND correlation_id IS NULL)
    )
);

CREATE INDEX media_resolved_location_ix_location
    ON media_resolved_location USING gist(location);
CREATE INDEX media_resolved_location_ix_origin
    ON media_resolved_location(position_origin);

CREATE TABLE media_correlation_state (
    media_id BIGINT PRIMARY KEY REFERENCES media_file(id) ON DELETE CASCADE,
    algorithm_version INTEGER NOT NULL,
    calculated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE media_correlation_media_work (
    media_id BIGINT PRIMARY KEY REFERENCES media_file(id) ON DELETE CASCADE,
    reason VARCHAR(64) NOT NULL,
    requested_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    attempt_count INTEGER NOT NULL DEFAULT 0,
    last_error VARCHAR(1000),
    retry_after TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX media_correlation_media_work_ix_requested
    ON media_correlation_media_work(requested_at, media_id);
CREATE INDEX media_correlation_media_work_ix_retry
    ON media_correlation_media_work(retry_after, requested_at, media_id);

CREATE TABLE media_correlation_track_work (
    track_id BIGINT PRIMARY KEY REFERENCES gps_track(id) ON DELETE CASCADE,
    reason VARCHAR(64) NOT NULL,
    requested_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX media_correlation_track_work_ix_requested
    ON media_correlation_track_work(requested_at, track_id);

CREATE OR REPLACE FUNCTION queue_media_correlation_for_media()
RETURNS TRIGGER AS $$
DECLARE
    target_media_id BIGINT;
BEGIN
    target_media_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.media_id ELSE NEW.media_id END;
    INSERT INTO media_correlation_media_work(media_id, reason, requested_at)
    VALUES (target_media_id, LOWER(TG_TABLE_NAME) || '_' || LOWER(TG_OP), CURRENT_TIMESTAMP)
    ON CONFLICT (media_id) DO UPDATE SET
        reason = EXCLUDED.reason,
        requested_at = EXCLUDED.requested_at,
        attempt_count = 0,
        last_error = NULL,
        retry_after = EXCLUDED.requested_at;
    PERFORM bump_data_freshness('media');
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION queue_media_correlation_for_media_file()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO media_correlation_media_work(media_id, reason, requested_at)
    VALUES (NEW.id, 'media_metadata_' || LOWER(TG_OP), CURRENT_TIMESTAMP)
    ON CONFLICT (media_id) DO UPDATE SET
        reason = EXCLUDED.reason,
        requested_at = EXCLUDED.requested_at,
        attempt_count = 0,
        last_error = NULL,
        retry_after = EXCLUDED.requested_at;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION queue_media_correlation_for_track()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO media_correlation_track_work(track_id, reason, requested_at)
    VALUES (NEW.id, 'track_' || LOWER(TG_OP), CURRENT_TIMESTAMP)
    ON CONFLICT (track_id) DO UPDATE SET
        reason = EXCLUDED.reason,
        requested_at = EXCLUDED.requested_at;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION queue_media_correlation_before_track_delete()
RETURNS TRIGGER AS $$
BEGIN
    INSERT INTO media_correlation_media_work(media_id, reason, requested_at)
    SELECT DISTINCT correlation.media_id, 'track_delete', CURRENT_TIMESTAMP
    FROM media_track_correlation correlation
    WHERE correlation.track_id = OLD.id
    ON CONFLICT (media_id) DO UPDATE SET
        reason = EXCLUDED.reason,
        requested_at = EXCLUDED.requested_at,
        attempt_count = 0,
        last_error = NULL,
        retry_after = EXCLUDED.requested_at;
    RETURN OLD;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER media_file_correlation_work
AFTER INSERT OR UPDATE OF exif_gps_location, exif_gps_date, exif_date_image_taken ON media_file
FOR EACH ROW EXECUTE FUNCTION queue_media_correlation_for_media_file();

CREATE TRIGGER media_time_correction_work
AFTER INSERT OR UPDATE OR DELETE ON media_time_correction
FOR EACH ROW EXECUTE FUNCTION queue_media_correlation_for_media();

CREATE TRIGGER media_manual_location_work
AFTER INSERT OR UPDATE OR DELETE ON media_manual_location
FOR EACH ROW EXECUTE FUNCTION queue_media_correlation_for_media();

CREATE TRIGGER gps_track_correlation_work
AFTER INSERT OR UPDATE OF start_date, end_date, load_status, duplicate_status, track_source ON gps_track
FOR EACH ROW EXECUTE FUNCTION queue_media_correlation_for_track();

CREATE TRIGGER gps_track_correlation_delete_work
BEFORE DELETE ON gps_track
FOR EACH ROW EXECUTE FUNCTION queue_media_correlation_before_track_delete();

INSERT INTO media_correlation_media_work(media_id, reason)
SELECT id, 'initial_projection'
FROM media_file
ON CONFLICT (media_id) DO NOTHING;

rollback.sql:
DROP TRIGGER IF EXISTS gps_track_correlation_delete_work ON gps_track;
DROP TRIGGER IF EXISTS gps_track_correlation_work ON gps_track;
DROP TRIGGER IF EXISTS media_manual_location_work ON media_manual_location;
DROP TRIGGER IF EXISTS media_time_correction_work ON media_time_correction;
DROP TRIGGER IF EXISTS media_file_correlation_work ON media_file;
DROP FUNCTION IF EXISTS queue_media_correlation_before_track_delete();
DROP FUNCTION IF EXISTS queue_media_correlation_for_track();
DROP FUNCTION IF EXISTS queue_media_correlation_for_media_file();
DROP FUNCTION IF EXISTS queue_media_correlation_for_media();
DROP TABLE IF EXISTS media_correlation_track_work;
DROP TABLE IF EXISTS media_correlation_media_work;
DROP TABLE IF EXISTS media_correlation_state;
DROP TABLE IF EXISTS media_resolved_location;
DROP TABLE IF EXISTS media_track_correlation;
DROP TABLE IF EXISTS media_manual_location;
DROP TABLE IF EXISTS media_time_correction;
